<p class="eyebrow">Wallet</p><h1>Transactions</h1><form class="search-form" method="get"><input name="q" placeholder="Search reference" value="<?= e($filters['q']??'') ?>"><select name="type"><option value="">All types</option><?php foreach(['DEPOSIT','INVESTMENT_PURCHASE','INVESTMENT_PROFIT','SHARE_SALE','WITHDRAWAL','ADMIN_CREDIT','ADMIN_DEBIT'] as $type): ?><option<?= ($filters['type']??'')===$type?' selected':'' ?>><?= e($type) ?></option><?php endforeach; ?></select><button class="button">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Type</th><th>Description</th><th>Amount</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><a href="<?= e(route('dashboard.transactions.show',['transaction'=>$t['reference']])) ?>"><?= e($t['reference']) ?></a></td><td><?= e($t['created_at']) ?></td><td><?= e($t['transaction_type']) ?></td><td><?= e($t['description']) ?></td><td><?= e($t['direction']) ?> <?= money((int)$t['amount_minor']) ?></td></tr><?php endforeach; ?></tbody></table></div>
